const listReviewTallies = `-- name: ListReviewTallies :many
WITH reviewed AS (
    SELECT
        v.task_id,
        v.snapshot_id
    FROM
        reviews v
    WHERE
        v.released_at IS NOT NULL
    UNION
    SELECT
        t.task_id,
        t.snapshot_id
    FROM
        review_threads t
    WHERE
        t.author_kind = 'human'
),
released AS (
    SELECT
        w.task_id::uuid AS task_id,
        COUNT(DISTINCT w.snapshot_id)::int AS snapshots
    FROM
        reviewed w
    GROUP BY
        w.task_id
),
concluded AS (
    SELECT DISTINCT ON (v.task_id)
        v.task_id,
        v.verdict,
        n.sha AS snapshot_sha
    FROM
        reviews v
        JOIN review_snapshots n ON n.id = v.snapshot_id
    WHERE
        v.released_at IS NOT NULL
        AND v.verdict IN ('approved', 'changes_requested')
    ORDER BY
        v.task_id,
        n.ordinal DESC,
        v.released_at DESC
)
SELECT
    r.task_id,
    r.snapshots,
    c.verdict,
    c.snapshot_sha
FROM
    released r
    LEFT JOIN concluded c ON c.task_id = r.task_id
`

type ListReviewTalliesRow struct {
	TaskID      string
	Snapshots   int32
	Verdict     NullReviewVerdict
	SnapshotSha *string
}

