const listUnlandedReviewSnapshots = `-- name: ListUnlandedReviewSnapshots :many
SELECT
    r.task_id::uuid AS task_id,
    r.ordinal,
    r.base_sha,
    r.sha,
    m.merged_at
FROM
    review_snapshots r
    LEFT JOIN LATERAL (
        SELECT
            p.merged_at
        FROM
            task_pull_requests o
            JOIN pull_requests p ON p.id = o.pull_request_id
        WHERE
            o.task_id = r.task_id
            AND p.merged_at IS NOT NULL
        ORDER BY
            p.merged_at DESC
        LIMIT 1) m ON TRUE
WHERE
    r.landed_at IS NULL
    AND EXISTS (
        SELECT
            1
        FROM
            agents a
        WHERE
            a.task_id = r.task_id
            AND a.archived_at IS NULL)
    AND (EXISTS (
            SELECT
                1
            FROM
                reviews v
            WHERE
                v.snapshot_id = r.id
                AND v.released_at IS NOT NULL)
            OR EXISTS (
                SELECT
                    1
                FROM
                    review_threads t
                WHERE
                    t.snapshot_id = r.id
                    AND t.author_kind = 'human'))
    ORDER BY
        r.task_id,
        r.ordinal DESC
`

